def maximumCandies(candies: list[int], k: int) -> int:
    lo, hi = 1, max(candies)
    ans = 0
    while lo <= hi:
        mid = (lo + hi) // 2
        piles = sum(c // mid for c in candies)
        if piles >= k:
            ans = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return ans

